import sys, time, torch, numpy as np
import triton
import triton.language as tl
sys.path.insert(0, '/tmp')
from solution import _ln_stats_kernel, _ln_map_kernel

dev = 'cuda'
M, N = 16, 64*256*256
x = torch.rand(M, N, device=dev)
w = torch.rand(N, device=dev)
b = torch.rand(N, device=dev)
mr = torch.rand(M*2, device=dev)
y = torch.empty_like(x)

def bench(fn, iters=20):
    fn(); torch.cuda.synchronize()
    g = torch.cuda.CUDAGraph()
    with torch.cuda.graph(g):
        for _ in range(iters):
            fn()
    torch.cuda.synchronize()
    s = torch.cuda.Event(enable_timing=True); e = torch.cuda.Event(enable_timing=True)
    s.record()
    for _ in range(5):
        g.replay()
    e.record(); torch.cuda.synchronize()
    return s.elapsed_time(e)/5/iters*1000

best_s = None
for SBN in [2048, 4096, 8192, 16384]:
    for SW in [4, 8, 16]:
        for NS in [1, 2, 4]:
            C = N // SBN
            partials = torch.empty(2*M*C, device=dev, dtype=torch.float32)
            try:
                t = bench(lambda: _ln_stats_kernel[(M*C,)](x, partials, M, N, C, BLOCK_N=SBN, num_warps=SW, num_stages=NS))
                if best_s is None or t < best_s[0]: best_s = (t, SBN, SW, NS)
            except Exception:
                pass
print('best stats:', best_s)

best_m = None
for NBN in [256, 512, 1024, 2048]:
    for NW in [2, 4, 8]:
        for NS in [1, 2, 4]:
            try:
                t = bench(lambda: _ln_map_kernel[(N//NBN,)](x, w, b, mr, y, M, N, BLOCK_N=NBN, num_warps=NW, num_stages=NS))
                if best_m is None or t < best_m[0]: best_m = (t, NBN, NW, NS)
            except Exception:
                pass
print('best map:', best_m)
